+}
+
+inline std::size_t max_compressed_bytes(std::size_t n) { return fsz_max_compressed_bytes(n); }
+inline std::size_t num_tiles(std::size_t n)            { return fsz_num_tiles(n); }
+inline const char* version()                            { return fsz_version(); }
+
+}
