+    } else {
+        v.x = (gi     < nbEle) ? data[gi]     : 0.0f;
+        v.y = (gi + 1 < nbEle) ? data[gi + 1] : 0.0f;
+        v.z = (gi + 2 < nbEle) ? data[gi + 2] : 0.0f;
